-- Report ID : RPT_032
-- Report    : WH Purchases Non Guaranteed Discounts
-- Module    : Finance
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     TRUNC(SYSDATE)                                        AS report_date,      oh.ORDER_NO                                           AS po_number,     oh.STATUS                                             AS po_status,     CASE oh.STATUS         WHEN 'W' THEN 'Worksheet'         WHEN 'S' THEN 'Submitted'         WHEN 'A' THEN 'Approved'         WHEN 'C' THEN 'Closed'         ELSE oh.STATUS     END                                                   AS po_status_desc,     oh.WRITTEN_DATE                                       AS po_written_date,     oh.NOT_BEFORE_DATE                                    AS not_before_date,     oh.NOT_AFTER_DATE                                     AS not_after_date,     oh.CURRENCY_CODE                                      AS po_currency,     oh.TERMS                                              AS payment_terms,      oh.SUPPLIER                                           AS supplier_id,     sp.SUP_NAME                                           AS supplier_name,     sp.SUP_STATUS                                         AS supplier_status,      ol.LOCATION                                           AS warehouse_id,     wh.WH_NAME                                            AS warehouse_name,     wh.STOCKHOLDING_IND                                   AS stockholding_ind,      im.DEPT                                               AS dept_no,     d.DEPT_NAME                                           AS dept_name,     im.CLASS                                              AS class_no,     c.CLASS_NAME                                          AS class_name,     im.SUBCLASS                                           AS subclass_no,     sc.SUB_NAME                                           AS subclass_name,      ol.ITEM                                               AS item_id,     im.ITEM_DESC                                          AS item_description,     im.STANDARD_UOM                                       AS uom,     im.PACK_IND                                           AS pack_ind,      ol.QTY_ORDERED                                        AS qty_ordered,     ol.QTY_RECEIVED                                       AS qty_received,     NVL(ol.QTY_ORDERED, 0) - NVL(ol.QTY_RECEIVED, 0)    AS qty_outstanding,      ol.UNIT_COST                                          AS gross_unit_cost,     ROUND(ol.QTY_ORDERED * ol.UNIT_COST, 4)              AS gross_total_cost,      odd.DEAL_ID                                           AS deal_id,     odd.DEAL_DETAIL_ID                                    AS deal_detail_id,      dh.BILLING_TYPE                                       AS billing_type,     CASE dh.BILLING_TYPE         WHEN 'OI'  THEN 'Off Invoice (Guaranteed - Net Cost)'         WHEN 'BB'  THEN 'Bill Back (Non-Guaranteed - Net-Net Cost)'         WHEN 'BBR' THEN 'Bill Back Rebate (Non-Guaranteed - Dead Net)'         WHEN 'VFP' THEN 'Vendor Funded Promotion (Non-Guaranteed - Dead Net)'         WHEN 'VFM' THEN 'Vendor Funded Markdown (Non-Guaranteed - Dead Net)'         ELSE dh.BILLING_TYPE     END                                                   AS billing_type_desc,      CASE dh.BILLING_TYPE         WHEN 'BB'  THEN 'NON-GUARANTEED - Bill Back Accrual'         WHEN 'BBR' THEN 'NON-GUARANTEED - Bill Back Rebate Accrual'         WHEN 'VFP' THEN 'NON-GUARANTEED - Vendor Funded Promotion'         WHEN 'VFM' THEN 'NON-GUARANTEED - Vendor Funded Markdown'         ELSE 'OTHER'     END                                                   AS discount_category,      odd.DISCOUNT_TYPE                                     AS discount_type,     CASE odd.DISCOUNT_TYPE         WHEN 'P' THEN 'Percentage'         WHEN 'A' THEN 'Fixed Amount'         WHEN 'F' THEN 'Free Goods'         ELSE odd.DISCOUNT_TYPE     END                                                   AS discount_type_desc,     odd.DISCOUNT_VALUE                                    AS discount_value,     odd.DISCOUNT_AMT_PER_UNIT                             AS discount_amt_per_unit,      ROUND(NVL(odd.DISCOUNT_AMT_PER_UNIT, 0)           * NVL(ol.QTY_ORDERED, 0), 4)                   AS discount_amount,     odd.LAST_CALC_DATE                                    AS discount_last_calc_date,     odd.PAID_IND                                          AS discount_paid_ind,      CASE         WHEN ROUND(ol.QTY_ORDERED * ol.UNIT_COST, 4) > 0         THEN ROUND(              (NVL(odd.DISCOUNT_AMT_PER_UNIT, 0) * NVL(ol.QTY_ORDERED, 0))              / (ol.QTY_ORDERED * ol.UNIT_COST) * 100, 2)     END                                                   AS discount_pct_of_gross,      ROUND(NVL(ol.QTY_ORDERED, 0) * NVL(ol.UNIT_COST, 0)           - (NVL(odd.DISCOUNT_AMT_PER_UNIT, 0) * NVL(ol.QTY_ORDERED, 0)), 4)                                                           AS net_cost_after_discount,      dh.COMMENTS                                           AS deal_description,     dh.TYPE                                               AS deal_type,     CASE dh.TYPE         WHEN 'A' THEN 'Annual Deal'         WHEN 'P' THEN 'Promotional Deal'         WHEN 'O' THEN 'PO Specific Deal'         WHEN 'M' THEN 'Vendor Funded Markdown'     END                                                   AS deal_type_desc,     dh.STATUS                                             AS deal_status,     dh.ACTIVE_DATE                                        AS deal_active_date,     dh.CLOSE_DATE                                         AS deal_close_date,     dh.SUPPLIER                                           AS deal_vendor_id,     dh.CURRENCY_CODE                                      AS deal_currency,     dh.EXT_REF_NO                                         AS deal_ext_ref_no,      dd.COST_APPL_IND                                      AS cost_apply_type,     dd.DEAL_CLASS                                         AS deal_class,     CASE dd.DEAL_CLASS         WHEN 'CU' THEN 'Cumulative'         WHEN 'CA' THEN 'Cascade'         WHEN 'EX' THEN 'Exclusive'     END                                                   AS deal_class_desc,     dd.DEAL_COMP_TYPE                                     AS deal_comp_type,     dd.TRAN_DISCOUNT_IND                                  AS tran_discount_ind,      ohd.TOTAL_DISCOUNT_AMT                                AS order_level_discount_amt,      CASE         WHEN dh.BILLING_TYPE IN ('BB','BBR')         THEN 'ACCRUED - Bill Back income will be invoiced by supplier'         WHEN dh.BILLING_TYPE IN ('VFP','VFM')         THEN 'ACCRUED - Vendor will fund via promotional income'         ELSE 'REVIEW'     END                                                   AS income_recognition_note  FROM     MFCS_RDS.RDS_WV_ORDHEAD                    oh      JOIN  MFCS_RDS.RDS_WV_ORDLOC              ol    ON  oh.ORDER_NO    = ol.ORDER_NO                                                      AND ol.LOC_TYPE   = 'W'      JOIN  MFCS_RDS.RDS_WV_ORDLOC_DISCOUNT    odd    ON  ol.ORDER_NO    = odd.ORDER_NO                                                      AND ol.ITEM        = odd.ITEM                                                      AND ol.LOCATION    = odd.LOCATION      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER         im    ON  ol.ITEM        = im.ITEM     JOIN  MFCS_RDS.RDS_WV_DEPS                d     ON  im.DEPT        = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS               c     ON  im.DEPT        = c.DEPT                                                      AND im.CLASS       = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS            sc    ON  im.DEPT        = sc.DEPT                                                      AND im.CLASS       = sc.CLASS                                                      AND im.SUBCLASS    = sc.SUBCLASS      JOIN  MFCS_RDS.RDS_WV_WH                  wh    ON  ol.LOCATION    = wh.WH      LEFT JOIN MFCS_RDS.RDS_WV_SUPS            sp    ON  oh.SUPPLIER    = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_DEAL_HEAD       dh    ON  odd.DEAL_ID    = dh.DEAL_ID                                                      AND dh.BILLING_TYPE IN ('BB','BBR','VFP','VFM')      LEFT JOIN MFCS_RDS.RDS_WV_DEAL_DETAIL     dd    ON  odd.DEAL_ID       = dd.DEAL_ID                                                      AND odd.DEAL_DETAIL_ID = dd.DEAL_DETAIL_ID      LEFT JOIN MFCS_RDS.RDS_WV_ORDHEAD_DISCOUNT ohd  ON  oh.ORDER_NO    = ohd.ORDER_NO                                                      AND ohd.DEAL_ID    = odd.DEAL_ID  WHERE     ol.LOC_TYPE = 'W'     AND dh.BILLING_TYPE IN ('BB','BBR','VFP','VFM')     AND oh.WRITTEN_DATE >= ADD_MONTHS(SYSDATE, -3)  ORDER BY     ROUND(NVL(odd.DISCOUNT_AMT_PER_UNIT, 0)           * NVL(ol.QTY_ORDERED, 0), 4)                   DESC,     oh.WRITTEN_DATE                                       DESC,     sp.SUP_NAME,     oh.ORDER_NO,     ol.ITEM